import { makeGrade, type Topic } from "./authoring";

const grade5: readonly Topic[] = [
  { slug: "atelier-de-dessin", title: "A drawing workshop: listen and clarify", words: ["DESSIN", "PLIE", "COLLE"], links: [["Plie la feuille", "Fold the sheet"], ["Au milieu", "In the middle"]], gap: ["Plie la", "feuille", "."],
    listening: ["Prends une feuille. Dessine deux cercles en haut. Écris ton prénom sous les cercles. Ne colorie pas les cercles.", ["What belongs above the name?", "Two circles", "Three stars", "A coloured square", "Deux cercles en haut places two circles above the name written underneath."]],
    scenes: [
      ["Prepare the materials", "At an art table, Prends une feuille means take a sheet. Plie la feuille means fold the sheet; découpe means cut out. Predict these actions from the materials, but wait for the complete instruction. Do not assume every workshop uses scissors.", "An adult reads three material requests in French; select the objects without reading.", ["What does plie request?", "Fold", "Colour", "Erase", "Plie is the command form used here for folding."]],
      ["Locate and order", "Model: Dessine une étoile au milieu. Ensuite, ajoute un cercle à droite. This means draw a star in the middle, then add a circle on the right. Au milieu describes position; ensuite describes order. Both matter when another person follows your drawing plan.", "Have an adult read a changed drawing plan; compare the result with the spoken positions.", ["Which expression gives an order clue?", "Ensuite", "Au milieu", "À droite", "Ensuite means next; the other expressions give positions."]],
      ["Repair an uncertain action", "Que veut dire découpe ? means what does découpe mean? Répétez la deuxième étape, s'il vous plaît asks for the second step again. Choose between a meaning question and repetition. Confirm with Je plie avant de dessiner ? — I fold before drawing?", "Give and receive a new two-step plan; ask one precise question and explain its effect.", ["Which question asks about a word's meaning?", "Que veut dire découpe ?", "Où est ma feuille ?", "Comment ça va ?", "Que veut dire asks what an expression means."]],
    ] },
  { slug: "le-sac-retrouve", title: "The recovered bag: listen for causes", words: ["SAC", "PARC", "PLUIE"], links: [["Il cherche", "He looks for"], ["Il retrouve", "He finds again"]], gap: ["Il cherche son", "sac", "."], pictures: ["bag", "book", "hat"],
    listening: ["Au parc, Malik ne trouve plus son sac. Il demande de l'aide à Jo. Jo regarde sous le banc et trouve le sac. Malik remercie Jo.", ["Who finds the missing bag?", "Jo", "Malik alone", "A shopkeeper", "Jo regarde sous le banc et trouve le sac identifies Jo as the finder."]],
    scenes: [
      ["Track the problem", "Original narrative: Éva arrive au parc. Elle cherche son chapeau près du banc. It says Éva arrives at the park and looks for her hat near the bench. Cherche gives the action, not a successful result. Keep the problem separate from a predicted ending.", "Hide the text while an adult reads; draw the person, place, and unresolved problem.", ["What does the narrative establish?", "Éva is looking for a hat", "Éva has already found it", "Éva bought a bench", "Cherche describes looking, not finding."]],
      ["Explain the change", "Un ami voit le chapeau sous le banc. Éva sourit et dit merci. A friend sees the hat under the bench; Éva smiles and says thank you. The smile supports a possible feeling of relief. It does not prove why the hat was there or who moved it.", "Listen to the continuation and retell the change with an evidence-based feeling.", ["Which detail supports relief?", "She smiles after the hat is found", "The bench has an unknown colour", "No friend appears", "The smile follows resolution of the problem."]],
      ["Compare retellings", "One listener says the hat was près du banc, near the bench; another says sous le banc, under it. Those describe the search and discovery respectively. Listen for which moment each phrase belongs to. D'abord means first and enfin means finally.", "Compare two spoken retellings; replay the passage and correct a misplaced detail.", ["Why can both location phrases occur?", "They describe different moments", "They are identical words", "The story has no location", "The first phrase describes the search; the second describes the finding."]],
    ] },
  { slug: "choisir-un-jeu", title: "Choose a game together", words: ["JEU", "TOUR", "REGLE"], links: [["Je préfère", "I prefer"], ["Et toi ?", "And you?"]], gap: ["Je", "préfère", " ce jeu."],
    scenes: [
      ["Ask about a preference", "Quel jeu préfères-tu ? asks which game you prefer. Je préfère le jeu de cartes answers with a card game. Et toi ? invites a return turn. Pictures or real game materials can support meaning; a partner may choose a different game from the one you rehearsed.", "Discuss two safe classroom games with an adult and ask a genuine preference question.", ["Which phrase asks for a preference?", "Quel jeu préfères-tu ?", "Où est le livre ?", "Il est petit.", "Préfères-tu asks what the partner prefers."]],
      ["Give a useful reason", "Je préfère ce jeu parce qu'il est court means I prefer this game because it is short. Tu préfères un jeu calme ? checks whether the partner prefers a quiet game. Parce que introduces a reason; it is not a command that everyone must share that preference.", "Take turns giving different reasons; restate the partner's reason before proposing a game.", ["What does parce que introduce?", "A reason", "A price", "A farewell", "Parce que means because."]],
      ["Negotiate a small plan", "On joue dix minutes, puis on change de jeu proposes playing ten minutes and then changing games. Ça te convient ? asks whether that works for the other person. A successful exchange reaches a understood plan, not a promise that both preferences are identical.", "Agree on a short game plan, then repeat after your partner changes one condition.", ["What does Ça te convient ? check?", "Whether the plan suits the partner", "The colour of the cards", "A person's surname", "The question checks agreement with a proposal."]],
    ] },
  { slug: "mon-objet-utile", title: "Present a useful object", words: ["LIVRE", "SAC", "CRAYON"], links: [["Il sert à", "It is used for"], ["Voici", "Here is"]], gap: ["Voici mon", "crayon", "."], pictures: ["pencil", "book", "bag"],
    scenes: [
      ["Plan a clear introduction", "Voici mon sac. Il est bleu. Je l'utilise pour transporter mes livres introduces a blue bag used to carry books. Begin with the object, then describe and explain its use. Transporter means carry or transport; livres means books, not pounds in this sentence.", "Choose an ordinary object and prepare three French cue phrases with their meanings.", ["What is the bag used for?", "Carrying books", "Measuring the rain", "Cooking eggs", "Pour transporter mes livres gives its purpose."]],
      ["Make the description audible", "Un petit livre and deux petits livres show singular and plural descriptions. The final written s is generally not sounded in these examples. Listen to a capable adult model the complete phrases. Pause after Voici mon livre before explaining what the book is about.", "Practise two descriptions for an adult; compare your pacing before and after feedback.", ["Which model describes more than one book?", "Deux petits livres", "Un petit livre", "Voici mon sac", "Deux and the written plurals indicate two books."]],
      ["Answer the audience", "Pourquoi utilises-tu ce crayon ? asks why you use this pencil. Parce qu'il écrit clairement means because it writes clearly. A reply about your favourite game would miss the question. If the question is unclear, request repetition before giving a relevant reason.", "Present the object, invite a question, answer it, and revise one unclear phrase.", ["Which reply answers why the pencil is used?", "Parce qu'il écrit clairement", "J'aime le parc", "Bonjour", "The reply provides a reason related to the pencil."]],
    ] },
  { slug: "une-petite-surprise", title: "Read a story about a small surprise", words: ["BOITE", "GRAINE", "FLEUR"], links: [["Une graine", "A seed"], ["Elle pousse", "It grows"]], gap: ["La", "graine", " pousse."],
    scenes: [
      ["Test a prediction", "Original text: Une petite boîte arrive dans la classe. Léa pense qu'elle contient des crayons. Elle ouvre la boîte : il y a des graines. A box arrives; Léa predicts pencils but finds seeds. The title or a guess does not override the stated contents.", "Read the text with an adult, record a prediction, and explain the detail that changes it.", ["What is actually in the box?", "Seeds", "Pencils", "A clock", "Il y a des graines gives the actual contents."]],
      ["Read the turning point", "Léa plante une graine. Une semaine plus tard, une feuille apparaît. Léa dessine la plante dans son cahier. She plants a seed; a week later a leaf appears and she draws it. Une semaine plus tard connects events across time rather than showing an immediate result.", "Read the continuation aloud in phrases and explain how the plant changes.", ["Which event occurs a week later?", "A leaf appears", "A pencil arrives", "The class disappears", "Une semaine plus tard introduces the appearance of a leaf."]],
      ["Verify a word", "A word wall places graine beside a seed drawing and plante beside a plant drawing. The related verb planter means to plant. Use the sentence to decide whether plante names the plant or describes an action; confirm with an adult or a children's dictionary.", "Build a three-word vocabulary note, read the whole story again, and name a useful clue.", ["Which resource would help distinguish graine and plante?", "A labelled drawing and context", "A random English rhyme", "Only the page number", "The illustrations and sentence meaning support vocabulary verification."]],
    ] },
  { slug: "horaire-du-club", title: "Read a club schedule", words: ["LUNDI", "MARDI", "CLUB"], links: [["À midi", "At noon"], ["La salle", "The room"]], gap: ["Le club commence à", "midi", "."],
    scenes: [
      ["Recognize the schedule", "Original notice: Club de lecture — mardi, à midi, salle 4. Apporte un livre. A reading club meets Tuesday at noon in room 4; bring a book. A schedule helps a reader plan attendance. The day, time, and place are useful features rather than story characters.", "Identify the notice's purpose and show an adult each detail required to attend.", ["Where does this club meet?", "Room 4", "At the park", "On a bus", "Salle 4 names the meeting room."]],
      ["Read a changed detail", "A second notice says Jeudi : salle 6. Mardi : salle 4. Thursday uses room 6; Tuesday uses room 4. Read across the correct day rather than selecting the first room number. Jeudi and mardi are different days even though both end with the letters di.", "Use a two-row schedule to tell an adult where to go on each day; verify both lines.", ["Which room belongs to Thursday?", "Room 6", "Room 4", "No room", "The line beginning Jeudi supplies salle 6."]],
      ["Use and reflect", "Apporte un livre means bring a book. N'oublie pas ton livre means do not forget your book. A reader can understand both by noticing the familiar noun and the instruction's purpose. Explain how the heading and short lines help locate information quickly.", "Create a pretend attendance plan and explain which feature prevented a wrong-room choice.", ["What should a participant bring?", "A book", "A saucepan", "A bicycle wheel", "Apporte un livre explicitly requests a book."]],
    ] },
  { slug: "inviter-un-ami", title: "Write an invitation to a classroom event", words: ["INVITE", "HEURE", "SALLE"], links: [["Je t'invite", "I invite you"], ["À bientôt", "See you soon"]], gap: ["Je t'", "invite", " au club."],
    scenes: [
      ["Plan for a reader", "An invitation must let its reader decide and attend. Model: Je t'invite à notre exposition. C'est vendredi à midi, dans la salle 3. This invites someone to an exhibition Friday at noon in room 3. Use imaginary details, not your home address or private contact information.", "Plan a classroom invitation with an adult using purpose, day, time, and school location.", ["Which detail tells the reader when?", "Vendredi à midi", "Je t'invite", "Notre exposition", "The day and time supply when the event happens."]],
      ["Repair missing content", "Draft: Viens voir nos dessins vendredi ! says come see our drawings Friday, but omits the time and place. Revision adds À midi, dans la salle 3. This changes usefulness, not just spelling. A greeting and friendly closing can suit a familiar peer.", "Write a draft, have the reader identify a missing detail, and add it in French.", ["Which revision makes the invitation more usable?", "Add time and place", "Only change ink colour", "Remove the day", "The reader needs time and place to attend."]],
      ["Edit and present", "Check vendredi, salle, and the accent in à against the model. A final invitation can combine a simple illustration with readable French. Keep the draft and final version to show an added detail and a spelling check. An adult assesses the real message, not the quiz score alone.", "Proofread, present the invitation to its pretend reader, and explain two different changes.", ["What does à mark in à midi?", "The expression meaning at noon", "A person's surname", "The end of a story", "À midi is the time expression at noon; keep its accent."]],
    ] },
  { slug: "decrire-avec-precision", title: "Make a description precise", words: ["PETIT", "BLEUE", "GRAND"], links: [["Un sac bleu", "A blue bag"], ["Une boîte bleue", "A blue box"]], gap: ["Une boîte", "bleue", "."],
    scenes: [
      ["Notice model agreement", "Compare un sac bleu, a blue bag, and une boîte bleue, a blue box. The model uses bleu with sac and bleue with boîte. Learn the noun with its article and verify the adjective pattern from a model; English word endings cannot determine French grammatical gender.", "Describe two classroom objects with an adult using verified article-and-adjective models.", ["Which model describes a blue box?", "Une boîte bleue", "Un sac bleu", "Une boîte midi", "The supplied feminine noun model uses bleue."]],
      ["Replace a vague expression", "C'est bien, it is good, may not explain why an object is useful. Le sac est léger means the bag is light; il porte trois livres means it carries three books. Choose a concrete description that helps the listener recognize an object, not an unexplained evaluation.", "Revise a vague two-line description by adding one observable detail in French.", ["Which description gives a concrete detail?", "Le sac est léger", "C'est bien", "C'est quelque chose", "Léger specifies a useful property, rather than a vague judgement."]],
      ["Check a complete sentence", "Model: Les petits sacs sont bleus. This means the small bags are blue. Les and sont accompany a plural subject here. Copying a single adjective from a list may leave the sentence inconsistent; use the complete model to check how its parts work together.", "Write and reread one singular and one plural description; explain a correction to an adult.", ["Which model is plural?", "Les petits sacs sont bleus", "Le petit sac est bleu", "Une boîte bleue", "Les, sacs, and sont establish the plural sentence."]],
    ] },
  { slug: "affiche-de-lecture", title: "Investigate a reading poster", words: ["LIRE", "AFFICHE", "MIDI"], links: [["Viens lire", "Come read"], ["Entrée libre", "Free admission"]], gap: ["Viens", "lire", " avec nous."],
    scenes: [
      ["Identify an invitation", "An original spoken message says Viens lire avec nous ! L'entrée est libre. Come read with us; admission is free. A cheerful delivery can invite participation, but it cannot establish that the event suits every person. Check the actual words before deciding what is promised.", "Listen to an adult's plain and enthusiastic versions; compare the same information and effect.", ["What does entrée libre mean here?", "Free admission", "A locked entrance", "A required meal", "The expression says admission is free in this event context."]],
      ["Look for missing information", "A pretend poster reads Fête de lecture ! Vendredi ! with a large book picture. It names a reading celebration Friday but leaves out time and place. The picture attracts attention and identifies a topic; it does not tell the reader where to go.", "Read the poster and ask an adult which two details must be added before attendance.", ["Which detail is missing?", "The place", "The word lecture", "The day", "The poster names Friday and reading but gives no location."]],
      ["Create a useful poster", "An improved poster can say Vendredi, à midi, salle 2. Apporte un livre. That gives a day, time, room, and material request. Use readable lettering and one relevant image. Avoid Le meilleur événement du monde, the best event in the world, unless treated as opinion rather than proof.", "Make a French poster and spoken invitation for an adult reader; revise after their response.", ["Which phrase gives a material request?", "Apporte un livre", "Salle 2", "Vendredi", "Apporte requests bringing a book."]],
    ] },
  { slug: "voix-du-quebec", title: "Meet Quebec voices through real resources", words: ["QUEBEC", "SOURCE", "BONJOUR"], links: [["La source", "The named origin of information"], ["Vous", "A form whose use depends on audience and context"]], gap: ["Je nomme ma", "source", "."],
    scenes: [
      ["Listen to a situated voice", "Grade 5 Core inquiry focuses on French-speaking communities in Quebec. With an adult, select a short public audio and related text by a Quebec creator through a community organization or the Bibliothèque et Archives nationales du Québec. Record the actual creator and location.", "Listen to an adult-selected Quebec creator; identify one stated detail and a greeting in context.", ["Which region is this grade's Core inquiry focus?", "Quebec", "Europe only", "An invented place", "The Grade 5 Core expectations identify Quebec communities."]],
      ["Read and compare carefully", "Locate the resource's named Quebec community on a map. Read a small excerpt and compare one documented activity or place with something you know. Bonjour is a greeting, but it does not prove how every Quebec person greets every visitor. Keep creator, audience, and setting attached to the example.", "Read the community text, map its place, and give a French oral summary with one respectful question.", ["What should stay with a cultural detail?", "Its source and context", "An invented universal rule", "A ranking of cultures", "A situated resource supports a specific comparison, not a stereotype."]],
      ["Write an attributed response", "Model: Dans cette ressource, je découvre… introduces what you discover in this resource. Selon… means according to and can name its creator. Use the real resource's greeting and closing as a context-sensitive model, with adult guidance about tu and vous; do not invent a quotation.", "Write a short sourced response and present it orally; distinguish one fact and one open question.", ["What does selon help introduce?", "The source of an account", "A guarantee everyone agrees", "A private password", "Selon attributes information to a source."]],
    ] },
];

const grade6: readonly Topic[] = [
  { slug: "preparer-la-sortie", title: "Prepare a school outing from spoken directions", words: ["SORTIE", "EAU", "HEURE"], links: [["Avant de partir", "Before leaving"], ["Si", "If"]], gap: ["Apporte de l'", "eau", "."],
    listening: ["Demain, nous partons à neuf heures. Apporte de l'eau et un chapeau. S'il pleut, la visite commence dans la salle 5. Sinon, attends près de la porte.", ["Where does the visit start if it rains?", "Room 5", "Near the door", "At home", "S'il pleut introduces the rain condition followed by dans la salle 5."]],
    scenes: [
      ["Listen for preparations", "Avant de partir, prépare ton sac means before leaving, prepare your bag. Apporte de l'eau et un chapeau means bring water and a hat. A listener preparing for a school outing needs materials as well as time; a list of nouns alone may miss a required action.", "An adult reads a changed preparation message; make and check a material list without seeing it.", ["What does avant de partir mean?", "Before leaving", "After eating", "Without returning", "Avant indicates before; partir means leave."]],
      ["Follow a condition", "S'il pleut, attends dans la salle. Sinon, attends près de la porte means if it rains, wait in the room; otherwise wait near the door. Si introduces a condition and sinon gives an alternative. Select the relevant branch rather than trying to carry out both locations at once.", "Listen to two weather conditions and choose the corresponding waiting place with an adult.", ["What does sinon introduce?", "The alternative condition", "A person's name", "A final greeting", "Sinon means otherwise in this direction."]],
      ["Confirm an essential detail", "Est-ce qu'on part à neuf heures ou à neuf heures et demie ? asks whether departure is at nine or nine thirty. A precise time question is more useful than saying Je ne comprends rien, I understand nothing, when you understood the materials but not the time.", "Ask a precise time or location question, restate the answer, and evaluate your listening notes.", ["Which question targets departure time?", "Est-ce qu'on part à neuf heures ?", "Quel chapeau préfères-tu ?", "Qui aime lire ?", "Part à neuf heures checks the departure time."]],
    ] },
  { slug: "le-jardin-change", title: "Listen to a garden report", words: ["JARDIN", "FEUILLE", "VENT"], links: [["La veille", "The day before"], ["Parce que", "Because"]], gap: ["Le", "vent", " déplace les feuilles."],
    listening: ["Hier, le vent a renversé un petit pot. Aujourd'hui, Sam remet la plante dans un pot plus grand. Il demande de l'aide parce que la terre est lourde.", ["Why does Sam ask for help?", "The soil is heavy", "The plant is blue", "The garden is closed", "Parce que la terre est lourde explicitly gives the reason."]],
    scenes: [
      ["Track two times", "Original report: Hier, le jardin était sec. Aujourd'hui, la pluie arrose les plantes. Yesterday the garden was dry; today rain waters the plants. Hier and aujourd'hui separate observations across time. Do not describe both observations as happening at the same moment.", "Listen to the report with text hidden and organize yesterday/today notes.", ["Which word signals yesterday?", "Hier", "Aujourd'hui", "Demain", "Hier means yesterday."]],
      ["Connect a cause and effect", "Le vent déplace les feuilles; la pluie mouille la terre says wind moves the leaves and rain wets the soil. Different causes produce different changes. Because the report states rain, it is not necessary to invent someone using a hose to explain wet soil.", "Retell one cause and effect, citing the heard words to an adult.", ["What wets the soil in the report?", "Rain", "A book", "A named gardener with a hose", "La pluie mouille la terre directly names rain."]],
      ["Separate observation and guess", "Je vois une petite feuille, I see a small leaf, reports an observation. La plante sera immense demain, the plant will be enormous tomorrow, predicts more than the evidence shows. A listener can ask Comment le sais-tu ?, how do you know, to request support respectfully.", "Discuss a report with a partner and separate one observation from one prediction.", ["Which statement is a direct observation?", "Je vois une petite feuille", "La plante sera immense demain", "Toutes les plantes poussent à la même vitesse", "Je vois reports what is seen rather than an unsupported prediction."]],
    ] },
  { slug: "resoudre-un-oubli", title: "Resolve a missing-material problem", words: ["CAHIER", "PRETER", "DEMAIN"], links: [["Puis-je emprunter", "May I borrow"], ["Je le rends", "I return it"]], gap: ["Puis-je", "emprunter", " un crayon?"],
    scenes: [
      ["Explain the need", "J'ai oublié mon cahier means I forgot my notebook. Puis-je emprunter une feuille ? asks may I borrow a sheet? Explain the missing material and ask for a practical solution rather than demanding a partner's possessions. The other person may offer an alternative.", "Role-play a forgotten school material with an adult and make a polite specific request.", ["What does emprunter mean?", "Borrow", "Throw away", "Describe a colour", "Emprunter requests temporary use."]],
      ["Respond to an alternative", "Je peux te prêter un crayon, mais pas mon cahier means I can lend you a pencil, but not my notebook. Mais marks a limit. A relevant answer acknowledges both the offer and the limit; it must not pretend that the notebook has also been offered.", "Listen to an offer with a limit and reply with a related alternative solution.", ["What has been offered?", "A pencil only", "The notebook and pencil", "A new desk", "Mais pas mon cahier excludes lending the notebook."]],
      ["Confirm return arrangements", "Je te le rends après l'activité means I return it to you after the activity. On se retrouve près de la porte ? asks about meeting near the door. A useful agreement includes what is borrowed and when it returns; confirm a change rather than reciting the first arrangement.", "Negotiate a pretend return plan and repeat when the partner changes the time.", ["Which expression states when to return it?", "Après l'activité", "Une feuille", "Près de la porte", "Après l'activité gives the time; près de la porte gives location."]],
    ] },
  { slug: "expliquer-une-experience", title: "Explain a safe observation demonstration", words: ["PAPIER", "SEC", "MOUILLE"], links: [["D'abord", "First"], ["Enfin", "Finally"]], gap: ["Le papier est", "mouillé", "."],
    scenes: [
      ["Organize the explanation", "D'abord, observe le papier sec. Ensuite, ajoute une goutte d'eau. Enfin, compare means first observe dry paper, next add a drop of water, finally compare. This safe demonstration needs a sequence and a purpose; use water only with adult approval and away from electronics.", "Plan and present the steps of an adult-approved paper-and-water observation.", ["What happens first?", "Observe dry paper", "Compare before observing", "Add many liquids", "D'abord marks the initial observation of dry paper."]],
      ["Describe instead of overclaiming", "Le papier devient mouillé means the paper becomes wet. Ce papier absorbe l'eau means this paper absorbs water. Say what the observation supports rather than concluding that every material absorbs water. Pronounce the key terms within the explanatory sentences, not only as isolated labels.", "Perform the safe demonstration and describe one observed change aloud to an adult.", ["Which wording limits the claim to the sample?", "Ce papier absorbe l'eau", "Tous les matériaux sont identiques", "Rien ne change jamais", "Ce papier refers to the tested sample rather than every material."]],
      ["Answer a method question", "Combien de gouttes as-tu ajoutées ? asks how many drops you added. J'ai ajouté une goutte answers with one drop. A listener checking the method needs that quantity, not merely the opinion C'était amusant, it was fun. Keep cue notes short enough to maintain contact with the listener.", "Answer a quantity question, then improve the explanation after one clarity suggestion.", ["Which reply answers the quantity question?", "J'ai ajouté une goutte", "C'était amusant", "Le papier est blanc", "Une goutte supplies the number of drops."]],
    ] },
  { slug: "la-reparation", title: "Read a story about repair and persistence", words: ["ROUE", "VELO", "AIDE"], links: [["Une roue", "A wheel"], ["Il essaie", "He tries"]], gap: ["Il demande de l'", "aide", "."],
    scenes: [
      ["Read the obstacle", "Original text: Le vélo de Nina fait un bruit. Elle s'arrête et demande l'aide d'un adulte. Nina's bicycle makes a noise; she stops and asks an adult for help. This is a safe response to an uncertain problem, not evidence that she already knows how to repair the bicycle.", "Read the opening and identify the problem and response using the text's words.", ["What does Nina do after hearing the noise?", "Stops and asks an adult for help", "Rides faster", "Repairs everything alone", "Elle s'arrête et demande l'aide explicitly gives her response."]],
      ["Interpret persistence", "L'adulte vérifie la roue. Nina observe, pose une question, puis essaie le vélo avec l'adulte. An adult checks the wheel; Nina observes, asks, and tries it with support. Her actions suggest curiosity and care. The passage does not say every noise has the same cause.", "Read the continuation aloud and explain a possible character trait with an actual action.", ["Which action supports curiosity?", "She asks a question", "She ignores the adult", "She throws away the bicycle", "Pose une question is evidence of wanting to understand."]],
      ["Learn a word family", "Réparer means repair; une réparation is a repair. Look for the shared répar- element, then confirm which form names an action or a thing. Reread the passage to connect new vocabulary with the problem. A word family supports meaning without proving every ending works in every sentence.", "Make a word-family note and reread for phrasing; identify one changed understanding.", ["Which word names the action?", "Réparer", "Une réparation", "Une roue", "Réparer is the infinitive verb; réparation is a noun."]],
    ] },
  { slug: "reglement-de-la-bibliotheque", title: "Read a library borrowing guide", words: ["PRET", "LIVRE", "RETOUR"], links: [["La date de retour", "The return date"], ["Sauf", "Except"]], gap: ["Vérifie la date de", "retour", "."],
    scenes: [
      ["Identify a guide's job", "Original guide: Emprunte deux livres. Rapporte-les vendredi. This asks the reader to borrow two books and bring them back Friday. A borrowing guide directs action; a story about a librarian would have a different purpose even if both use livre and bibliothèque.", "Read a short pretend borrowing guide and identify its purpose and two key requirements.", ["How many books does the guide allow?", "Two", "Friday books", "No books", "Deux livres supplies the quantity."]],
      ["Notice an exception", "Prêt : sept jours, sauf les nouveaux livres : trois jours means loans last seven days except new books, which last three days. Sauf matters more than the first number for a new book. A reader should not apply the general period to an explicitly excluded category.", "Use an adult-created loan table to choose the correct return period for two book types.", ["How long is a new book loan?", "Three days", "Seven days", "Three weeks", "The exception gives trois jours for nouveaux livres."]],
      ["Explain your route through the text", "A heading such as Nouveaux livres helps locate the exception. Date de retour names a return date; it is not necessarily the date of borrowing. Explain which heading and words guided the decision. Ask for a missing date rather than inventing one from the general rule.", "Make a pretend return reminder and explain which text feature prevented a late return.", ["What does date de retour identify?", "When to bring the book back", "The author's birth date", "A book's colour", "Retour concerns returning the borrowed item."]],
    ] },
  { slug: "compte-rendu-du-club", title: "Write a short club report", words: ["CLUB", "DESSIN", "BILAN"], links: [["Nous avons", "We have / we did in this model"], ["Le bilan", "The review of what happened"]], gap: ["Notre", "club", " prépare une affiche."],
    scenes: [
      ["Select information for absent readers", "A club report helps an absent member understand what happened. Model: Mardi, notre club a préparé une affiche. Nous avons choisi le titre. Tuesday the club prepared a poster and chose its title. Select actual activities and next actions, using a supported model rather than invented achievements.", "Plan a report on a pretend club session with an adult using event, result, and next action.", ["Who especially needs this report?", "An absent club member", "Only a person buying shoes", "No reader", "The report's purpose is to communicate the session to someone who missed it."]],
      ["Clarify the next action", "Draft: Nous avons dessiné. À bientôt ! says we drew but leaves the reader unsure what happens next. Add La prochaine fois, nous ajouterons les images — next time we will add images. A supported future model can clarify a plan without claiming it already happened.", "Draft and revise a four-sentence report after a reader asks about the next meeting.", ["Which phrase introduces the next session?", "La prochaine fois", "Mardi dernier", "Nous avons dessiné", "La prochaine fois means next time."]],
      ["Produce readable work", "Check the past-action model a préparé and avons choisi against a reliable classroom model. Put the date and title where a reader can find them. Distinguish adding a missing next step from correcting an accent. The adult checks the actual report, use of resources, and revision evidence.", "Edit the report, share its final version, and explain one content and one language change.", ["Which is a content change?", "Adding the next planned action", "Only correcting préparé's accent", "Only changing pencil", "A next action adds information the reader needs."]],
    ] },
  { slug: "liens-de-cause-et-ordre", title: "Choose cause and sequence links", words: ["PUIS", "CAUSE", "DONC"], links: [["Parce que", "Introduces a reason"], ["Puis", "Introduces a following action"]], gap: ["Il pleut,", "donc", " nous restons dedans."],
    scenes: [
      ["Compare relationships", "Nous restons dedans parce qu'il pleut means we stay inside because it rains. Nous rangeons les crayons, puis nous lisons means we put away pencils, then read. Parce que explains a cause; puis places actions in order. Replacing one with the other can change what the sentence explains.", "Match cause and order sentences to simple drawings and explain the relation aloud.", ["Which link introduces a reason?", "Parce que", "Puis", "Enfin", "Parce que supplies a cause or reason."]],
      ["Make a conclusion clear", "Il pleut, donc nous restons dedans means it rains, therefore we stay inside. Donc introduces a consequence. The sentence does not claim that rain forces every group to stay inside; it explains this group's choice. Keep the subject and situation clear when using a useful model.", "Write two linked sentences about a pretend classroom choice using parce que and donc.", ["What relation does donc show here?", "A consequence", "A greeting", "A book title", "Donc links the rain to the group's resulting choice."]],
      ["Check reference", "Le cahier est sur la table. Il est ouvert says the notebook is on the table and it is open. Il refers to cahier in this model, not the feminine table. When two objects could fit a pronoun, name the intended one. A precise revision makes the reader's job easier.", "Edit an ambiguous object description with an adult, then explain the clarified reference.", ["What is open in the model?", "The notebook", "The table", "An unnamed door", "Il refers back to the masculine cahier in this model."]],
    ] },
  { slug: "annonce-du-club-nature", title: "Evaluate a nature-club announcement", words: ["NATURE", "CLUB", "PREUVE"], links: [["Tout le monde", "Everyone"], ["Une preuve", "Evidence"]], gap: ["Cherche une", "preuve", "."],
    scenes: [
      ["Question a broad claim", "A pretend announcement says Tout le monde adore notre club ! — everyone loves our club. That is a broad opinion claim, not measured evidence. A warm voice may make it appealing. Compare it with Des élèves de notre club aiment observer les plantes, some club students like observing plants.", "Listen to two adult-read announcements and identify which claim needs supporting evidence.", ["Which expression makes the broadest claim?", "Tout le monde", "Des élèves", "Notre club", "Tout le monde asserts everyone, beyond the stated evidence."]],
      ["Check useful information", "An event card states Mercredi, de midi à midi et demie, salle 7. That means Wednesday from noon to half past noon in room 7. A plant image suggests topic but does not add a start time. Read the start and end together rather than treating midi et demie as the start.", "Read the event card and explain duration and location to a pretend new member.", ["How long is the meeting?", "Thirty minutes", "Seven hours", "One day", "Noon to half past noon is a thirty-minute interval."]],
      ["Communicate accurately", "An improved invitation can explain the activity: Nous observerons les feuilles, we will observe leaves, and invite questions. A simple French message with accurate details is more useful than unexplained superlatives. Use an original image or an appropriately credited one; do not claim another creator's work.", "Create a short French invitation and read it aloud; revise an unclear or unsupported phrase.", ["Which phrase explains the activity?", "Nous observerons les feuilles", "Le meilleur de tous", "Mercredi seul", "The phrase states what participants will observe."]],
    ] },
  { slug: "francophonies-du-canada", title: "Explore eastern, western, and northern Canadian voices", words: ["CANADA", "CARTE", "SOURCE"], links: [["Une communauté", "A situated group of people"], ["Selon la source", "According to the source"]], gap: ["Je situe le lieu sur une", "carte", "."],
    scenes: [
      ["Choose regional voices", "Grade 6 Core explores French-speaking communities in eastern, western, and northern Canada. Ask an adult to choose public French resources from community organizations such as the Société de l'Acadie, the Fédération des francophones de la Colombie-Britannique, and the Association franco-yukonnaise.", "Listen to one approved excerpt from each broad region and record its real creator and place.", ["Which regions belong to this inquiry?", "Eastern, western, and northern Canada", "Only one neighbourhood in Paris", "Only Quebec", "Grade 6 Core expands inquiry to these Canadian regions."]],
      ["Compare without flattening", "Locate the named places on a map and read a related community-authored description. Notice a specific activity or language-use setting, not a universal lifestyle. Tu and vous choices depend on relationship and context; compare actual examples without treating a region as a single speaking pattern.", "Map the sources, read a short excerpt, and present one careful comparison in supported French.", ["What is a defensible comparison?", "A specific sourced detail across two places", "Everyone has the same custom", "One accent proves a person's identity", "A comparison must preserve the sources' particular contexts."]],
      ["Write with attribution", "Model: Cette ressource présente… means this resource presents; Je voudrais savoir… means I would like to know. Use these to write a short introduction and inquiry question. Credit each creator and distinguish direct words from your summary. Ask what another local voice might add.", "Write and orally share a sourced three-region note with one open question and suitable greeting.", ["Which expression introduces an inquiry question?", "Je voudrais savoir", "Tout le monde fait pareil", "Je n'ai pas de source", "Je voudrais savoir expresses a desire to learn rather than a universal claim."]],
    ] },
];

const grade7: readonly Topic[] = [
  { slug: "itineraire-modifie", title: "Understand a changed itinerary", words: ["TRAJET", "RETARD", "ARRET"], links: [["En raison de", "Because of"], ["Au lieu de", "Instead of"]], gap: ["Le bus a du", "retard", "."],
    listening: ["Le groupe prend le bus à dix heures au lieu de neuf heures. En raison des travaux, le rendez-vous est devant la bibliothèque, pas devant l'école. Apportez votre fiche.", ["Where is the new meeting point?", "In front of the library", "In front of the school", "Inside the bus garage", "Devant la bibliothèque replaces the explicitly rejected school meeting point."]],
    scenes: [
      ["Distinguish old and new", "Nous partons à dix heures au lieu de neuf heures means we leave at ten instead of nine. The old time remains in the sentence to explain the change; it is not a second departure option. In a spoken update, mark what changed and which information remains valid.", "Listen to a changed school itinerary and annotate old/new details on a pretend plan.", ["Which departure time is now valid?", "Ten", "Nine", "Both equally", "Au lieu de replaces the nine o'clock departure with ten."]],
      ["Listen for a reason", "En raison des travaux, le groupe passe par une autre rue means because of roadworks the group uses another street. En raison de explains the cause; une autre gives an alternative without naming it. Ask for the new street if it is necessary rather than inventing a route.", "An adult reads a route update; separate a stated reason from a missing necessary detail.", ["What causes the route change?", "Roadworks", "A reported snowstorm", "An invented festival", "Des travaux is the cause stated in the message."]],
      ["Confirm a revised plan", "Donc, nous attendons devant la bibliothèque à dix heures, c'est bien cela ? confirms waiting in front of the library at ten. A concise restatement checks several linked details. Note whether background noise or writing too much made you miss a change, then select a strategy for that obstacle.", "Confirm two changed details with an adult and describe a strategy addressing an actual obstacle.", ["What makes this confirmation useful?", "It restates place and time", "It ignores the update", "It changes to a private topic", "The confirmation checks the combined revised arrangement."]],
    ] },
  { slug: "deux-temoignages", title: "Listen to two accounts of one event", words: ["RECIT", "PLUIE", "INDICE"], links: [["À mon avis", "In my opinion"], ["J'ai entendu", "I heard"]], gap: ["Je cherche un", "indice", "."],
    listening: ["Mina dit : Nous avons quitté le terrain parce qu'il pleuvait. Hugo dit : Je n'ai pas vu la pluie; j'étais dans la salle. Les deux parlent du même moment, mais pas du même endroit.", ["Why might their observations differ?", "They were in different places", "They necessarily describe different days", "Both admit inventing everything", "Hugo was indoors, while Mina describes leaving the field."]],
    scenes: [
      ["Compare viewpoints", "Original accounts: Nora says J'ai entendu un bruit près de la porte, I heard a sound near the door. Ilyes says Je regardais la fenêtre, I was watching the window. Their attention differs. The second statement does not disprove the first or identify the noise's cause.", "Listen to two short accounts without text and record what each speaker actually observed.", ["What did Nora report?", "A sound near the door", "A broken window", "A known cause of the sound", "J'ai entendu un bruit reports a sound, not its cause."]],
      ["Weigh an inference", "Il semblait inquiet, he seemed worried, is an interpretation. Il a demandé si tout allait bien, he asked whether everything was all right, supplies an action that can support it. Use semblait to signal uncertainty. A confident tone alone does not turn an inference into a directly observed fact.", "Ask a partner for evidence behind an interpretation, then compare it with the heard action.", ["Which phrase signals a tentative interpretation?", "Il semblait inquiet", "Il a posé une question", "Il était près de la porte", "Semblait means seemed, indicating an interpretation."]],
      ["Reconcile rather than erase", "Les deux récits peuvent apporter des détails différents means both accounts may contribute different details. A synthesis can state what agrees, what differs, and what remains uncertain. Request the relevant part again rather than forcing the account with fewer words to be wrong.", "Produce a brief oral synthesis with agreements, differences, and one unresolved question.", ["What belongs in a careful synthesis?", "An unresolved question where evidence is missing", "An invented cause", "Automatic rejection of one speaker", "Missing evidence should remain a question rather than become an invented fact."]],
    ] },
  { slug: "negocier-un-projet", title: "Negotiate roles in a group project", words: ["ROLE", "PROJET", "DELAI"], links: [["Je propose", "I propose"], ["Cependant", "However"]], gap: ["Je", "propose", " de préparer le plan."],
    scenes: [
      ["Offer a role", "Je peux préparer les images; qui veut écrire le texte ? offers to prepare images and asks who wants to write. The proposal names an actual responsibility. A group's needs matter as well as preferences; ask about available time and resources before assuming a role is easy.", "Role-play assigning three project tasks, with each partner giving a realistic preference.", ["What responsibility is offered?", "Preparing images", "Writing everything alone", "Buying private gifts", "Préparer les images names the offered task."]],
      ["Acknowledge a constraint", "Je voudrais écrire, cependant je ne suis pas disponible mardi means I would like to write, however I am not available Tuesday. Cependant signals a contrast between willingness and availability. Restate the constraint before proposing another meeting or dividing the task.", "Respond to a partner's unavailable day with a respectful relevant alternative.", ["What is the stated constraint?", "Tuesday availability", "Lack of interest in all writing", "A missing book title", "Ne suis pas disponible mardi gives a specific scheduling limit."]],
      ["Make the agreement checkable", "Nous terminons le brouillon jeudi, puis nous relisons vendredi means we finish the draft Thursday and reread Friday. A useful agreement names responsibilities and deadlines. Confirm who does which task, then practise repairing the plan if one resource is delayed.", "Complete a spoken role/deadline agreement and adapt it after an adult changes one resource.", ["What happens Friday?", "Rereading", "The initial drafting deadline", "Nothing is stated", "Relisons vendredi gives the Friday action."]],
    ] },
  { slug: "presenter-un-choix", title: "Present a recommendation with reasons", words: ["CHOIX", "RAISON", "PUBLIC"], links: [["Je recommande", "I recommend"], ["Un avantage", "An advantage"]], gap: ["Je", "recommande", " cette option."],
    scenes: [
      ["Build a supported recommendation", "Je recommande une affiche lisible parce que les visiteurs doivent trouver la salle means I recommend a readable poster because visitors must find the room. State the option, reason, and relevant audience need. A personal favourite is not automatically the most suitable communication choice.", "Prepare a short recommendation on two pretend project formats with reasons for a named audience.", ["What reason supports readability?", "Visitors need to find the room", "All colours are forbidden", "Every person has the same preference", "The recommendation is tied to a practical visitor need."]],
      ["Use phrasing to separate ideas", "D'abord, voici le problème. Ensuite, voici notre solution creates a clear problem-solution structure. Pause between the two ideas, stress necessary terms, and explain unfamiliar vocabulary for the listener. Reading cue words with no connecting message would not communicate the recommendation.", "Rehearse a problem-solution presentation, noting one term that needs an explanation.", ["Which structure is being used?", "Problem then solution", "An unordered shopping list", "A greeting without content", "Problème followed by solution establishes this structure."]],
      ["Respond to a challenge", "Et si nous avons peu de temps ? asks what if there is little time. Nous pouvons choisir un format plus simple offers a simpler format. An audience question can reveal a useful condition your initial recommendation missed. Revise your recommendation rather than merely repeating your first reason.", "Present, answer a time-constraint question, and revise your option after feedback.", ["Which response addresses limited time?", "Choose a simpler format", "Discuss only the weather", "Repeat that all options are perfect", "Un format plus simple is a relevant adjustment to the constraint."]],
    ] },
  { slug: "le-message-incomplet", title: "Read a story about an incomplete message", words: ["MESSAGE", "CLE", "DOUTE"], links: [["Pourtant", "Yet / however"], ["Elle hésite", "She hesitates"]], gap: ["Elle", "hésite", " avant de répondre."],
    scenes: [
      ["Identify the ambiguity", "Original story: Alex trouve un mot : « Je serai près de la porte. » Il y a deux portes dans la salle. Alex hésite. A note names a door, but the room has two. The hesitation has a textual cause: an ambiguous location, not proof that Alex dislikes the writer.", "Read the opening and explain how one missing detail creates the problem.", ["Why is the location unclear?", "The room has two doors", "The note names no room anywhere in the story", "Alex cannot see any door", "Deux portes makes près de la porte insufficiently precise."]],
      ["Read the resolution", "Alex demande : « La porte près de la fenêtre ? » La réponse précise : « Non, celle près du tableau. » The clarification rules out the window door and names the board-side door. Read dialogue with different phrasing for question and answer while preserving the exact information.", "Read the exchange aloud and show how the question leads to a precise answer.", ["Which door is intended?", "The one near the board", "The one near the window", "Both doors simultaneously", "Celle près du tableau is the final clarification."]],
      ["Interpret the theme", "The actions suggest that asking a precise question can be more effective than guessing. To support that theme, cite the ambiguity and its resolution. Pourtant, however or yet, often signals contrast; use the surrounding sentences to determine what is being contrasted rather than translating it alone.", "Explain a possible theme using two details and verify one connecting word in context.", ["Which theme fits these events?", "Clarification can solve ambiguity", "Questions always create trouble", "Every door looks identical", "The specific question resolves the incomplete location message."]],
    ] },
  { slug: "comparer-des-fiches", title: "Compare two information cards", words: ["FICHE", "DUREE", "LIEU"], links: [["La durée", "Duration"], ["Gratuit", "Free of charge"]], gap: ["Vérifie la", "durée", "."],
    scenes: [
      ["Identify comparable features", "Card A: Atelier de dessin, 30 minutes, salle 1. Card B: Atelier de récit, 45 minutes, salle 2. Compare workshop type, duration, and place on the same basis. A larger heading may attract attention but does not make one activity longer or better than stated.", "Build a comparison table from two adult-created workshop cards and cite each feature.", ["Which workshop lasts longer?", "The story workshop", "The drawing workshop", "Both last thirty minutes", "45 minutes exceeds the drawing workshop's 30 minutes."]],
      ["Check a condition", "Gratuit pour les élèves; réservation nécessaire means free for students, reservation required. Free admission does not cancel the reservation condition. Read the full eligibility and registration line before advising another person; distinguish cost from what must be done before attendance.", "Use a pretend visitor profile to explain cost and registration without inventing eligibility.", ["Does free admission remove the reservation requirement?", "No, a reservation is still necessary", "Yes, all conditions disappear", "Only if the heading is blue", "The card explicitly retains réservation nécessaire."]],
      ["Evaluate usefulness", "One card gives an activity and duration but omits the place. A reader planning attendance cannot fill the gap by assuming the other card's room. Request the missing detail and explain which feature aided your comparison. This reflection identifies a reading process, not simply the preferred workshop.", "Recommend a card revision and explain how you checked comparable details and conditions.", ["What should be done when the place is omitted?", "Request the missing place", "Copy another event's place", "Invent a room number", "Different events need their own verified location."]],
    ] },
  { slug: "lettre-de-proposition", title: "Draft a proposal letter", words: ["LETTRE", "BUT", "PROJET"], links: [["Nous proposons", "We propose"], ["Cordialement", "A courteous formal closing"]], gap: ["Nous", "proposons", " un coin de lecture."],
    scenes: [
      ["Choose a formal purpose", "Nous proposons un coin de lecture pour les pauses means we propose a reading corner for breaks. A letter to a school adult needs a clear request, reason, and realistic details. Bonjour followed by an appropriate title may fit the setting; ask an adult to verify the salutation convention.", "Plan a fictional school proposal letter with audience, request, reason, and needed resource.", ["What is being proposed?", "A reading corner", "A private business sale", "A new transport route", "Un coin de lecture names the proposed school space."]],
      ["Develop rather than repeat", "Draft: Nous voulons un coin. C'est bien. This says we want a corner and it is good, but lacks explanation. Add Il permettrait de lire calmement, it would allow quiet reading, using an adult-supported model. Explain a practical benefit without claiming guaranteed results for everyone.", "Write a draft, request specific content feedback, and add a benefit with a supported model.", ["Which addition develops the reason?", "It would allow quiet reading", "Only a bigger title", "A copied unrelated slogan", "The addition explains a practical purpose for the proposed space."]],
      ["Edit for a formal reader", "Check nous proposons, paragraph order, accents, and a suitable closing such as Cordialement against the chosen model. Keep the letter's request distinct from a claim that approval has already been granted. Readability and attribution of researched information matter alongside correct written conventions.", "Proofread the letter, present it to an adult reader, and compare content and convention changes.", ["Which statement should not be claimed without approval?", "The proposal has already been accepted", "The letter makes a request", "The writer gives a reason", "A request is not evidence that the recipient has approved it."]],
    ] },
  { slug: "accord-et-reference", title: "Use agreement and reference clearly", words: ["ACCORD", "SUJET", "PRONOM"], links: [["Ils préparent", "They prepare, plural masculine or mixed model"], ["Elle prépare", "She prepares"]], gap: ["Les élèves", "préparent", " le texte."],
    scenes: [
      ["Check the subject and verb", "Compare L'élève prépare le texte and Les élèves préparent le texte: one student prepares, and the students prepare. The written ending changes even when these verb forms sound alike. Identify the subject's number before checking the model; hearing alone may not reveal written agreement.", "Write singular and plural project sentences, identify the subject, and verify the verb form.", ["Which form fits Les élèves in the model?", "Préparent", "Prépare", "Préparer as an unchanged sentence verb", "The supplied plural subject model uses préparent."]],
      ["Control a pronoun reference", "Maya donne le cahier à Lila. Elle le lit is ambiguous about who reads it because both people can be elle. Rewrite Lila lit le cahier if Lila is intended. A correct-looking pronoun can still make meaning unclear; clarity may require a name rather than another pronoun.", "Revise two-person messages by naming the intended subject and explaining the ambiguity.", ["Which revision identifies Lila as reader?", "Lila lit le cahier", "Elle le lit unchanged", "Elles quelque chose", "Naming Lila resolves the ambiguous elle."]],
      ["Apply written conventions", "Model: Où est le cahier ? Le cahier est sur la table. A question uses an accent in où and a question mark; the answer ends as a statement. Check language conventions in a complete meaningful exchange. Use the same focused checklist on an original letter paragraph, not only these models.", "Edit an original paragraph for one agreement, one reference, and one punctuation choice.", ["Which mark closes the model question?", "A question mark", "No mark by rule", "An invented symbol", "The question Où est le cahier ? is punctuated as a question."]],
    ] },
  { slug: "titre-et-preuve", title: "Compare a headline with its evidence", words: ["TITRE", "PREUVE", "CHOIX"], links: [["Certains", "Some"], ["Tous", "All"]], gap: ["Le texte dit", "certains", ", pas tous."],
    scenes: [
      ["Listen for scope", "An original spoken announcement says Plusieurs élèves ont choisi la lecture, several students chose reading. A headline says Tous les élèves choisissent la lecture, all students choose reading. Plusieurs does not support tous. Scope words change how much evidence a claim requires.", "Listen to an announcement, then compare the scope of its wording with a pretend headline.", ["Which word makes the wider claim?", "Tous", "Plusieurs", "Lecture", "Tous includes everyone; plusieurs only means several."]],
      ["Inspect presentation choices", "A poster's enormous Tous and tiny Plusieurs in a footnote send conflicting impressions. Read both instead of relying on the largest word. Describe how emphasis might influence a reader while checking the actual statement. Do not infer a creator's hidden motives as a fact without evidence.", "Annotate a pretend poster's emphasis and explain a supported concern to an adult.", ["Which evaluation is supported?", "The emphasis overstates the smaller claim", "The creator's identity is certainly known", "Every viewer believes the claim", "The conflicting scope words support concern about overstatement."]],
      ["Write a bounded message", "A accurate school update can say Plusieurs participants ont préféré cette activité, several participants preferred this activity. It preserves a limited observation rather than turning it into universal approval. Name the actual observation method if one was used; do not invent survey results for an attractive headline.", "Create a short French update from provided pretend observations, preserving scope and needed details.", ["What should not be invented?", "Survey results", "An original readable title", "A clearly labelled pretend example", "Evidence must not be manufactured to support a message."]],
    ] },
  { slug: "francophonies-des-ameriques", title: "Explore francophone voices in the Americas beyond Canada", words: ["CARTE", "SOURCE", "RECIT"], links: [["Un témoignage", "A situated personal account"], ["Je me demande", "I wonder"]], gap: ["Je nomme le lieu du", "récit", "."],
    scenes: [
      ["Select actual voices", "Grade 7 Core focuses on French-speaking communities in the Americas outside Canada. An adult can select suitable community-authored French material from a Haitian cultural creator or a Louisiana organization such as CODOFIL. Identify the precise place and creator rather than making a continent-wide claim.", "Listen to two approved public sources from named communities and record their provenance.", ["Which scope belongs to Grade 7 Core?", "The Americas outside Canada", "Canada alone", "Europe alone", "The official Grade 7 scope specifies the Americas beyond Canada."]],
      ["Locate and contextualize", "Map the sources' actual locations and read a related text. A person's account of a language or activity belongs to that context. French may coexist with other languages; do not infer that every person in a named place speaks French or identifies alike. Observe the source's actual social language.", "Read, locate, and present one sourced detail in French with a respectful comparison and question.", ["What can one account establish?", "A particular experience in context", "Every person's experience", "A universal ranking of languages", "A single source supports a situated account, not universal claims."]],
      ["Compose a careful response", "Dans ce témoignage… means in this account; Je me demande… introduces I wonder. Write a response that uses these forms to distinguish sourced observation from inquiry. Verify greeting and closing with the resource and adult support. Credit creator and place, and never supply an invented quotation.", "Write and orally present a sourced response, including one uncertainty and a suitable closing.", ["Which phrase signals a question rather than a fact?", "Je me demande", "Tout le monde est pareil", "Il n'y a aucun doute", "Je me demande introduces an open inquiry."]],
    ] },
];

const grade8: readonly Topic[] = [
  { slug: "consignes-sous-conditions", title: "Interpret conditional project instructions", words: ["OPTION", "DELAI", "FICHE"], links: [["À condition de", "Provided that"], ["Sauf si", "Unless"]], gap: ["Vérifie le", "délai", "."],
    listening: ["Vous pouvez présenter vendredi à condition d'envoyer votre plan jeudi. Sauf si la salle est fermée, nous utilisons la salle 8. Si elle est fermée, la présentation a lieu dans la bibliothèque.", ["What must happen before Friday's presentation?", "Send the plan Thursday", "Close the library", "Present Wednesday", "À condition d'envoyer votre plan jeudi makes Thursday submission a requirement."]],
    scenes: [
      ["Identify a requirement", "Vous pouvez choisir le format à condition de garder les informations essentielles means you may choose the format provided that essential information is kept. Permission and requirement coexist. A listener who remembers only pouvez choisir misses the condition that limits the choice.", "Listen to an adult-read project brief and distinguish a permission from its attached requirement.", ["What limits the format choice?", "Keeping essential information", "No condition at all", "Choosing the longest title", "À condition de introduces the requirement."]],
      ["Resolve an exception", "Utilisez la salle 8, sauf si elle est fermée means use room 8 unless it is closed. An alternative should be stated or requested; do not invent one. Draw a two-branch note for open/closed conditions and check what the instruction actually says about each branch.", "Use an open/closed scenario to follow a spoken brief and request an unstated alternative.", ["What does sauf si introduce?", "An exception", "A greeting", "A guaranteed open room", "Sauf si means unless and limits the general instruction."]],
      ["Check before acting", "Pour confirmer, nous envoyons le plan jeudi et présentons vendredi ? restates sending the plan Thursday and presenting Friday. Explain which condition still requires checking. Choose a note-taking strategy that preserves requirements without distracting you from the next spoken change.", "Restate the complete brief to an adult and evaluate whether your notes preserve the conditions.", ["What does the confirmation check?", "Both submission and presentation timing", "Only a preferred colour", "An unrelated travel date", "The restatement combines the two linked deadlines."]],
    ] },
  { slug: "entrevue-et-inference", title: "Listen critically to an original interview", words: ["ENTREVUE", "CHOIX", "INDICE"], links: [["Selon moi", "In my view"], ["En revanche", "By contrast"]], gap: ["Selon", "moi", ", ce choix est utile."],
    listening: ["Journaliste : Pourquoi avez-vous changé le plan ? Invitée : Nous avions moins de temps. Nous avons gardé les étapes essentielles, mais réduit les illustrations. Le résultat est plus court, pas forcément meilleur.", ["What does the guest claim about the result?", "It is shorter, not necessarily better", "It is certainly perfect", "It has more illustrations", "Plus court, pas forcément meilleur distinguishes length from quality."]],
    scenes: [
      ["Identify question and response", "Original interview: Pourquoi as-tu choisi ce projet ? — Il me permet de travailler avec une autre classe. Why choose the project? It allows work with another class. A reason responds to the question; the answer does not establish that collaboration improved every outcome.", "Listen to an interview with text hidden and identify the question, response, and bounded reason.", ["What reason does the speaker give?", "Working with another class", "Guaranteed universal success", "The room's paint colour", "Travailler avec une autre classe is the stated reason."]],
      ["Notice a qualified judgement", "Selon moi, le plan est plus clair; en revanche, il demande plus de temps means in my view the plan is clearer; by contrast it needs more time. The speaker weighs a benefit against a cost. Selon moi marks a personal judgement, not an independently established measurement.", "Retell the benefit and cost and distinguish the speaker's judgement from a reported fact.", ["Which phrase marks personal judgement?", "Selon moi", "Plus de temps", "Le plan", "Selon moi means in my view."]],
      ["Probe an unsupported inference", "If a listener concludes the longer plan must be better, ask Quel indice soutient cette conclusion ?, what clue supports that conclusion? The interview may support a trade-off without resolving it. Synthesize what is heard and a question that would require more evidence rather than certainty.", "Discuss competing interpretations and formulate one evidence-seeking follow-up question.", ["What would a useful follow-up ask for?", "Evidence supporting the quality claim", "A louder repeat of the opinion only", "An invented result", "A quality inference needs evidence beyond duration."]],
    ] },
  { slug: "debattre-dune-solution", title: "Discuss a solution and counterproposal", words: ["SOLUTION", "RAISON", "LIMITE"], links: [["Je comprends, mais", "I understand, but"], ["Pourrions-nous", "Could we"]], gap: ["Pourrions-nous", "adapter", " le plan?"],
    scenes: [
      ["State a position with scope", "Je propose de prolonger l'atelier de dix minutes pour terminer les échanges proposes ten extra minutes to finish discussion. Give a bounded reason related to the shared task rather than claiming everyone wants a longer session. Ask whether the group has a scheduling constraint.", "Discuss a pretend workshop extension with an adult, giving a position, reason, and question.", ["What does the proposal seek?", "Ten additional minutes", "A different school term", "Guaranteed agreement", "Prolonger de dix minutes defines the requested change."]],
      ["Represent the counterproposal", "Je comprends ton idée, mais le groupe suivant arrive à midi means I understand your idea, but the next group arrives at noon. Restate that constraint accurately before responding. Pourrions-nous commencer plus tôt ? asks could we begin earlier, a relevant alternative rather than ignoring the objection.", "Respond to a time constraint with a fair restatement and one feasible counterproposal.", ["Which alternative addresses the constraint?", "Begin earlier", "Assume the next group disappears", "Repeat without listening", "Starting earlier can address the fixed noon arrival."]],
      ["Summarize an agreement", "Nous gardons la fin à midi et commençons dix minutes plus tôt means keep the noon ending and begin ten minutes earlier. Summarize what was agreed and why, leaving unaccepted ideas labelled as proposals. Assess your use of follow-up questions and clarity after an unexpected partner response.", "Conduct a second discussion with a changed condition and summarize the final agreement.", ["What stays unchanged in the agreement?", "The noon ending", "The start time", "Every proposed detail", "Gardons la fin à midi explicitly preserves the end time."]],
    ] },
  { slug: "presentation-avec-limites", title: "Present a reasoned recommendation with limitations", words: ["OPTION", "LIMITE", "BILAN"], links: [["Un critère", "A criterion"], ["Toutefois", "However"]], gap: ["Cette option a une", "limite", "."],
    scenes: [
      ["Choose transparent criteria", "Nous comparons les options selon le coût, le temps et la clarté means we compare options by cost, time, and clarity. State criteria before recommending a format. A preference for a colourful design should not silently replace the announced criteria when an audience must make a practical choice.", "Prepare a two-option recommendation with three stated criteria and a supported conclusion.", ["Which word names the comparison basis?", "Critère", "Slogan", "Prénom", "A critère is a basis for judging or comparing options."]],
      ["Explain a limitation aloud", "Cette option est rapide; toutefois, elle contient moins d'exemples means this option is quick; however it contains fewer examples. Toutefois signals a limitation alongside the benefit. Slow down at the contrast so listeners hear both, and explain a necessary term instead of relying on jargon.", "Present the benefit and limitation, using phrasing and a brief vocabulary explanation.", ["What limitation is stated?", "Fewer examples", "No benefit exists", "An invented cost", "Contient moins d'exemples gives the stated limitation."]],
      ["Adapt to a question", "Si notre public découvre le sujet, faut-il plus d'exemples ? asks whether a new-to-topic audience needs more examples. An answer can reconsider the criteria's importance for that audience. Recommending a different option after a relevant question demonstrates reasoning, not failure to memorize a speech.", "Answer an audience question and revise one part of the recommendation with an explanation.", ["Why might the recommendation change?", "Audience needs change the weight of a criterion", "All recommendations are guesses", "Questions must be ignored", "A new audience need can change which option best fits the criteria."]],
    ] },
  { slug: "le-choix-du-narrateur", title: "Read for narrator perspective", words: ["RECIT", "VOIX", "REGARD"], links: [["Je pensais", "I thought"], ["Pourtant", "Yet"]], gap: ["Le", "narrateur", " raconte son point de vue."],
    scenes: [
      ["Separate perspective from certainty", "Original story: Je pensais que personne ne lisait mon affiche. Pourtant, deux élèves m'ont posé des questions. The narrator thought nobody read the poster, yet two students asked questions. First-person belief is not a complete account of every reader's attention; the later detail qualifies it.", "Read the opening and separate the narrator's initial belief from the later stated event.", ["Which detail challenges the belief?", "Two students asked questions", "The poster's size is unknown", "Nobody speaks at any time", "Questions from two students contradict the claim that nobody engaged."]],
      ["Read contrast expressively", "Je suis resté silencieux, puis j'ai expliqué mon idée means I remained silent, then explained my idea. Puis sequences actions; pourtant in the earlier passage signals contrast. Read each relation with appropriate phrasing rather than applying the same dramatic tone to every connecting word.", "Read both passages aloud and explain the difference between sequence and contrast.", ["Which link gives sequence?", "Puis", "Pourtant", "Personne", "Puis means then and orders the two actions."]],
      ["Support a theme cautiously", "A possible theme is that an initial impression can change when new evidence appears. Support it with the narrator's belief and the questions, not an invented ending where everyone agrees. Verify impression and expression in a dictionary; similar-looking words do not have interchangeable meanings.", "Write a short evidence-based theme note, verify vocabulary, and name a next reading goal.", ["Which theme fits the passage?", "New evidence can revise an impression", "Every poster is ignored", "Every question guarantees agreement", "The narrator's initial impression is challenged by actual questions."]],
    ] },
  { slug: "lire-des-conditions", title: "Read eligibility and registration conditions", words: ["FICHE", "INSCRIT", "DATE"], links: [["Jusqu'au", "Until the stated date"], ["Obligatoire", "Required"]], gap: ["L'inscription est", "obligatoire", "."],
    scenes: [
      ["Identify a registration form", "Original event guide: Inscription jusqu'au jeudi. Autorisation de l'école obligatoire. Registration is available until Thursday and school permission is required. A form's purpose is to gather and verify information; do not enter private real details into a pretend online exercise.", "Inspect a fictional registration guide and identify deadlines, requirements, and safe placeholder fields.", ["What is required?", "School permission", "Only a favourite colour", "No preparation", "Autorisation de l'école obligatoire states the requirement."]],
      ["Interpret limits together", "Places limitées : dix groupes; deux élèves par groupe means ten groups with two students per group. The group limit and group size answer different questions. Do not read dix as a total student limit or assume open capacity without checking whether registration is full.", "Use a pretend capacity table to distinguish group count, group size, and available places.", ["What does dix groupes count?", "Groups", "Individual students directly", "Hours", "The number is explicitly attached to groupes."]],
      ["Evaluate completeness", "A notice may give the deadline but omit how to register. Request the missing procedure and explain which textual feature helped locate the known conditions. Reading critically means noting usable information and a genuine gap, not labelling every short notice unreliable.", "Advise a pretend participant using verified conditions and one necessary clarification question.", ["What must be clarified if absent?", "How to register", "An invented participant biography", "A universal event custom", "An attendee needs the procedure as well as the deadline."]],
    ] },
  { slug: "rapport-argumente", title: "Write a balanced project evaluation", words: ["RAPPORT", "RÉSULTAT", "LIMITE"], links: [["Le résultat", "The outcome"], ["Une amélioration", "An improvement"]], gap: ["Nous proposons une", "amélioration", "."],
    scenes: [
      ["Plan evidence and audience", "A project evaluation for a school adult can organize goal, observation, limitation, and next step. Model: Notre but était de rendre l'information lisible, our goal was to make information readable. Use actual or explicitly fictional observations; avoid inventing measured outcomes or personal records.", "Plan a balanced evaluation from adult-provided pretend project observations.", ["Which belongs in the plan?", "A limitation as well as an outcome", "Only unsupported praise", "Private participant records", "A balanced evaluation includes constraints and results."]],
      ["Revise an overstatement", "Draft: Tout le monde a compris immédiatement says everyone understood immediately. The observations mention only three readers explaining the message. Revise Trois lecteurs ont expliqué le message clairement, three readers explained it clearly. The bounded statement fits the available evidence.", "Draft a short evaluation and revise a claim whose scope exceeds the provided observations.", ["Which version fits evidence from three readers?", "Trois lecteurs ont expliqué le message", "Tout le monde a compris", "Personne n'a lu", "The revised statement preserves the observed sample rather than universalizing it."]],
      ["Edit a reasoned conclusion", "Nous ajouterons un exemple pour les nouveaux lecteurs means we will add an example for new readers. Link the improvement to the reported difficulty. Check agreement, connective meaning, accents, and paragraph order using resources. Keep evidence of a content revision distinct from language editing.", "Finish the evaluation, proofread it, and explain why the proposed next step follows the evidence.", ["What makes the conclusion reasoned?", "The improvement addresses a documented need", "It adds unrelated praise", "It removes all limitations", "A recommendation should respond to the observed difficulty."]],
    ] },
  { slug: "precision-des-temps", title: "Clarify time, agreement, and sentence relations", words: ["HIER", "DEMAIN", "ACCORD"], links: [["Nous avons choisi", "We chose / have chosen"], ["Nous choisirons", "We will choose"]], gap: ["Demain, nous", "choisirons", " le titre."],
    scenes: [
      ["Use supported time models", "Hier, nous avons choisi le thème; demain, nous choisirons le titre means yesterday we chose the theme and tomorrow we will choose the title. Match a reliable past or future model with the intended time. Do not change only hier to demain while leaving a contradictory model unexamined.", "Write a two-time project update and verify the verb models and intended timeline.", ["Which form belongs to the future model?", "Nous choisirons", "Nous avons choisi", "Hier alone", "Choisirons is the supplied future-tense form."]],
      ["Check descriptive agreement", "Les affiches sont lisibles means the posters are readable. Les textes sont courts means the texts are short. Identify the noun and number, then verify the describing form in a resource. Similar pronunciation can hide written endings; an editing check must consider spelling as well as what you hear.", "Describe two plural project products and verify agreement against an adult-approved model.", ["Which model describes readable posters?", "Les affiches sont lisibles", "Le texte est court", "Une affiche hier", "The complete model connects plural affiches to lisibles."]],
      ["Keep logical links precise", "Le texte est court, mais il reste clair means the text is short, but remains clear. Le texte est clair parce que les étapes sont expliquées gives a reason for clarity. Mais and parce que communicate different relations. Explain why a chosen link fits the claim in your actual evaluation draft.", "Edit a paragraph for time, agreement, and cause/contrast, then explain one meaningful choice.", ["Which link gives a cause?", "Parce que", "Mais", "Pourtant", "Parce que introduces the explanation or reason."]],
    ] },
  { slug: "message-et-credibilite", title: "Evaluate message credibility and design", words: ["SOURCE", "PREUVE", "PUBLIC"], links: [["Vérifiable", "Can be checked"], ["Une opinion", "A judgement or preference"]], gap: ["Cette affirmation demande une", "preuve", "."],
    scenes: [
      ["Distinguish a checkable statement", "An original announcement says L'atelier dure trente minutes, the workshop lasts thirty minutes. It also says C'est l'expérience parfaite, it is the perfect experience. Duration can be checked against a schedule; perfection is a judgement and depends on a reader's needs rather than a clock.", "Listen to an adult-read promotion and identify one checkable statement and one opinion.", ["Which statement is directly checkable against a schedule?", "The workshop lasts thirty minutes", "The experience is perfect", "Every person will love it", "A timetable can verify duration, not universal perfection."]],
      ["Check provenance and emphasis", "A card repeats a claim without naming its source. Large lettering may create confidence but leaves provenance unresolved. Ask who created the message, when, for which audience, and where evidence can be checked. Do not equate attractive design with verified information or assume anonymous means false.", "Read a pretend card, annotate its evidence gap, and explain how emphasis affects its impression.", ["What remains unresolved without provenance?", "The claim's source", "The visible font size", "The number of printed words", "A missing source prevents checking where the claim originated."]],
      ["Create an accountable update", "A useful update names a real or explicitly fictional basis: Selon notre tableau d'essai, three pretend readers found the room. Keep fictional results labelled as fictional. Use readable design and suitable French, then invite the audience to identify the main claim and its support.", "Create a French update from labelled pretend evidence and revise after an adult's credibility check.", ["How should fictional evidence be presented?", "Clearly labelled as fictional", "As a real survey", "As an unnamed community quotation", "Fictional examples must not masquerade as actual research."]],
    ] },
  { slug: "voix-francophones-europe", title: "Explore situated francophone voices in Europe", words: ["EUROPE", "SOURCE", "CARTE"], links: [["Cette voix", "This particular voice"], ["Un contexte", "The setting and circumstances"]], gap: ["Je précise le", "contexte", "."],
    scenes: [
      ["Choose European resources", "Grade 8 Core examines French-speaking communities in Europe. An adult can select age-appropriate public French material from named creators or organizations in France, Belgium, or Switzerland, such as a community library or cultural association. Verify actual authorship and language before assigning a regional label.", "Listen to approved community-created sources from two named European places and note provenance.", ["Which geographic scope fits Grade 8 Core?", "Europe", "Only northern Canada", "Only Ontario", "The Grade 8 Core intercultural expectations specify Europe."]],
      ["Compare situated conventions", "Map each resource's place and read a related community text. Observe how a specific speaker addresses a particular audience and compare greetings or written forms in context. A single use of vous is not evidence that every person in a country always uses it. Include similarities and differences without ranking cultures.", "Read and orally compare two sourced examples, with creator, audience, and an open question.", ["What does one use of vous establish?", "A form used in that context", "A universal rule for a country", "Every speaker's identity", "One example supports a contextual observation, not a nationwide rule."]],
      ["Write a sourced synthesis", "Ces deux ressources présentent… means these two resources present. Use the form to summarize actual details and then signal uncertainty with Il faudrait d'autres sources, more sources would be needed. Verify suitable greeting and closing, credit creators, and distinguish paraphrase from quotation.", "Write a short sourced synthesis and present it aloud, including one comparison and research limit.", ["Which statement honestly expresses a research limit?", "Il faudrait d'autres sources", "Une voix représente tout le monde", "La source n'a aucune importance", "More sources may be needed for a broader conclusion."]],
    ] },
];

